import QtQuick
import QtQuick.Layouts
import QtQuick.Controls
import Quickshell
import qs.services
import qs.modules.common
import qs.modules.common.widgets

Rectangle {
    id: root
    implicitWidth: 320
    implicitHeight: 52
    radius: Appearance.rounding.normal
    color: Appearance.colors.surfaceContainer

    readonly property real volume: (Audio.sink && Audio.sink.audio) ? Audio.sink.audio.volume : 0
    readonly property bool isMuted: (Audio.sink && Audio.sink.audio) ? Audio.sink.audio.muted : false

    RowLayout {
        anchors.fill: parent
        anchors.margins: 6
        spacing: 8

        RippleButton {
            id: muteBtn
            implicitWidth: 40
            implicitHeight: 40
            radius: Appearance.rounding.full
            color: root.isMuted ? Appearance.colors.errorContainer : Appearance.colors.surfaceContainerHigh
            onClicked: {
                if (Audio.sink && Audio.sink.audio) {
                    Audio.sink.audio.muted = !Audio.sink.audio.muted;
                }
            }

            MaterialSymbol {
                anchors.centerIn: parent
                name: root.isMuted ? "volume_off" : (root.volume > 0.5 ? "volume_up" : (root.volume > 0 ? "volume_down" : "volume_mute"))
                color: root.isMuted ? Appearance.colors.onErrorContainer : Appearance.colors.onSurface
                font.pixelSize: 20
            }
        }

        StyledSlider {
            id: slider
            Layout.fillWidth: true
            Layout.alignment: Qt.AlignVCenter
            value: root.volume
            from: 0
            to: 1
            onMoved: {
                if (Audio.sink && Audio.sink.audio) {
                    Audio.sink.audio.volume = slider.value;
                    if (Audio.sink.audio.muted && slider.value > 0) {
                        Audio.sink.audio.muted = false;
                    }
                }
            }
        }

        StyledText {
            text: `${Math.round(root.volume * 100)}%`
            font.pixelSize: 12
            font.weight: Font.DemiBold
            color: Appearance.colors.onSurfaceVariant
            Layout.preferredWidth: 36
            horizontalAlignment: Text.AlignRight
            Layout.alignment: Qt.AlignVCenter
        }
    }
}

