Item {
    id: root
    property bool checked: false
    property string onIcon: "check"
    property string offIcon: "close"
    signal toggled(bool state)

    implicitWidth: 52
    implicitHeight: 32

    Rectangle {
        id: track
        anchors.fill: parent
        radius: height / 2
        color: root.checked ? Appearance.colors.primary : Appearance.colors.surfaceContainerHighest
        border.color: root.checked ? Appearance.colors.primary : Appearance.colors.outline
        border.width: root.checked ? 0 : 2

        Behavior on color { ColorAnimation { duration: 180; easing.type: Easing.OutCubic } }
        Behavior on border.color { ColorAnimation { duration: 180 } }

        Rectangle {
            id: thumb
            width: root.checked ? 24 : 16
            height: width
            radius: width / 2
            anchors.verticalCenter: parent.verticalCenter
            x: root.checked ? parent.width - width - 4 : 4
            color: root.checked ? Appearance.colors.onPrimary : Appearance.colors.outline

            Behavior on x { NumberAnimation { duration: 200; easing.type: Easing.OutBack } }
            Behavior on width { NumberAnimation { duration: 150 } }
            Behavior on color { ColorAnimation { duration: 180 } }

            MaterialSymbol {
                anchors.centerIn: parent
                name: root.checked ? root.onIcon : root.offIcon
                font.pixelSize: 12
                color: root.checked ? Appearance.colors.primary : Appearance.colors.surfaceContainerHighest
                visible: root.checked || mouseArea.containsMouse
            }
        }
    }

    MouseArea {
        id: mouseArea
        anchors.fill: parent
        hoverEnabled: true
        cursorShape: Qt.PointingHandCursor
        onClicked: {
            root.checked = !root.checked;
            root.toggled(root.checked);
        }
    }
}

