Rectangle {
    id: root
    property string activeProfile: PowerProfiles.activeProfile ?? "balanced"

    function cycleProfile() {
        if (root.activeProfile === "power-saver") PowerProfiles.setProfile("balanced");
        else if (root.activeProfile === "balanced") PowerProfiles.setProfile("performance");
        else PowerProfiles.setProfile("power-saver");
    }

    implicitWidth: 160
    implicitHeight: 56
    radius: Appearance.rounding.normal
    color: root.activeProfile === "performance" ? Appearance.colors.errorContainer : Appearance.colors.surfaceContainerHigh
    Behavior on color { ColorAnimation { duration: 180 } }

    MouseArea {
        anchors.fill: parent
        cursorShape: Qt.PointingHandCursor
        onClicked: root.cycleProfile()
    }

    RowLayout {
        anchors.fill: parent
        anchors.margins: 10
        spacing: 10

        MaterialSymbol {
            name: root.activeProfile === "performance" ? "bolt" : (root.activeProfile === "power-saver" ? "energy_savings_leaf" : "speed")
            font.pixelSize: 22
            color: root.activeProfile === "performance" ? Appearance.colors.onErrorContainer : Appearance.colors.onSurface
        }

        ColumnLayout {
            Layout.fillWidth: true
            spacing: 2

            StyledText {
                text: "Power Mode"
                font.pixelSize: 13
                font.weight: Font.Medium
                color: root.activeProfile === "performance" ? Appearance.colors.onErrorContainer : Appearance.colors.onSurface
            }

            StyledText {
                text: root.activeProfile.charAt(0).toUpperCase() + root.activeProfile.slice(1)
