                implicitWidth: 32
                implicitHeight: 32
                radius: Appearance.rounding.full
                color: Appearance.colors.surfaceContainerHigh
                onClicked: GlobalStates.settingsOpen = !GlobalStates.settingsOpen
                MaterialSymbol {
                    anchors.centerIn: parent
                    name: "settings"
                    font.pixelSize: 18
                    color: Appearance.colors.onSurface
                }
            }
        }

        GridLayout {
            Layout.fillWidth: true
            columns: 2
            rowSpacing: 8
            columnSpacing: 8

            Rectangle {
                Layout.fillWidth: true
                implicitHeight: 56
                radius: Appearance.rounding.normal
                color: Appearance.colors.primary
                RowLayout {
                    anchors.fill: parent
                    anchors.margins: 10
                    MaterialSymbol { name: "wifi"; color: Appearance.colors.onPrimary; font.pixelSize: 20 }
                    StyledText { text: "Wi-Fi"; color: Appearance.colors.onPrimary; font.weight: Font.Medium }
                }
            }

            Rectangle {
                Layout.fillWidth: true
                implicitHeight: 56
                radius: Appearance.rounding.normal
                color: Appearance.colors.surfaceContainerHigh
                RowLayout {
                    anchors.fill: parent
                    anchors.margins: 10
                    MaterialSymbol { name: "bluetooth"; color: Appearance.colors.onSurface; font.pixelSize: 20 }
                    StyledText { text: "Bluetooth"; color: Appearance.colors.onSurface; font.weight: Font.Medium }
                }
            }
        }

        StyledSlider {
            Layout.fillWidth: true
            value: (Audio.sink && Audio.sink.audio) ? Audio.sink.audio.volume : 0.5
            onMoved: {
                if (Audio.sink && Audio.sink.audio) Audio.sink.audio.volume = value;
            }
        }
    }
}
